<title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0f1117;
    --card: #181b24;
    --border: #262a36;
    --text: #e0e2ea;
    --muted: #8b8fa5;
    --accent: #5b8af5;
    --accent2: #43d9ad;
    --accent3: #f5a623;
    --accent4: #e05252;
    --accent5: #b07ce8;
  }
  * { margin:0; padding:0; box-sizing:border-box; }
  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    padding: 0;
  }
  .container { max-width: 1200px; margin: 0 auto; padding: 40px 24px; }

  header {
    text-align: center;
    padding: 60px 24px 40px;
    background: linear-gradient(180deg, #161a28 0%, var(--bg) 100%);
    border-bottom: 1px solid var(--border);
  }
  header h1 {
    font-size: 2.2rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    margin-bottom: 8px;
  }
  header .subtitle {
    color: var(--muted);
    font-size: 1rem;
    max-width: 720px;
    margin: 0 auto;
  }
  header .meta {
    margin-top: 16px;
    font-size: 0.82rem;
    color: var(--muted);
  }

  /* KPI strip */
  .kpi-strip {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 16px;
    margin: 32px 0 48px;
  }
  .kpi-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px 18px;
    text-align: center;
  }
  .kpi-card .kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: var(--accent);
    line-height: 1.2;
  }
  .kpi-card:nth-child(2) .kpi-value { color: var(--accent2); }
  .kpi-card:nth-child(3) .kpi-value { color: var(--accent3); }
  .kpi-card:nth-child(4) .kpi-value { color: var(--accent5); }
  .kpi-card:nth-child(5) .kpi-value { color: var(--accent4); }
  .kpi-card .kpi-label {
    font-size: 0.82rem;
    color: var(--muted);
    margin-top: 6px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  section {
    margin-bottom: 48px;
  }
  section h2 {
    font-size: 1.4rem;
    font-weight: 700;
    margin-bottom: 8px;
