    border-bottom: 2px solid var(--accent);
    display: inline-block;
  }
  section h3 {
    font-size: 1.1rem;
    font-weight: 600;
    margin: 24px 0 12px;
    color: var(--accent);
  }
  p, li { color: var(--text); font-size: 0.95rem; margin-bottom: 10px; }

  .chart-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin: 20px 0;
  }
  .chart-row.full { grid-template-columns: 1fr; }
  .chart-box {
    background: var(--card);
    border: 1px solid var(--border);
